    def test_each_step_that_reads_the_variable_maps_it_from_the_repository_variable(self):
        """The workflows loaded with yq: each step of the trust, post and comment jobs and of rescreen.yml whose script
        (with .github/review/held.sh in the place of the line that sources it) reads the name that a step maps to
        ${{ vars.REPO_PAIRS_IMPORT_PATHS }} maps that name to it in its own env, and reads each name that it maps. The
        post job's decision step, the comment job's label step, the rescreen pass's step (which relabels a head whose
        recorded value is not the value now) and the trust job's step (which runs the pass's functions again for a
        stop) do, and no script holds the expression itself."""
        jobs = [(job, JOBS[job]) for job in ("trust", "post", "comment")] + [("rescreen", RESCREEN["jobs"]["rescreen"])]
        steps = [(job, s) for job, value in jobs for s in value["steps"]]
        names = {k for _job, s in steps for k, v in s.get("env", {}).items() if v == self.VARIABLE}
        self.assertTrue(names)
        mapped = set()
        for job, s in steps:
            run = sourced(s.get("run", ""))
            self.assertNotIn("vars.REPO_PAIRS_IMPORT_PATHS", run)
            for name in names:
                reads = re.search(rf"\$\{{?{name}\b", run) is not None
                maps = s.get("env", {}).get(name) == self.VARIABLE
                with self.subTest(job=job, step=s.get("name"), name=name):
                    self.assertEqual(reads, maps)
                if maps:
                    mapped.add((job, s["name"]))
        self.assertLessEqual({("trust", TRUST), ("post", self.DECIDE), ("comment", self.LABEL),
                              ("rescreen", RESCREEN_JOB)}, mapped)
        for job, value in jobs:
            self.assertNotIn(self.VARIABLE, json.dumps({k: v for k, v in value.items() if k != "steps"}))

    def test_while_the_hold_lasts_a_change_that_is_not_markdown_alone_gets_no_check_run(self):
        """While SOUNDNESS_HOLD is "true", with a stand-in model that misses the soundness verdict (it passes each
        one), and soundness.json as the gather job writes it from this repository's own dune files (proofs): a .v
        file, only tools/gen_checker.py, only a dune file with an echo rule, only a .hex file under theories/Examples/
        and only tools/check_one.py each get the person verdict of the soundness rule (R8), which counts each file that
        is not a Markdown file. A pass at such a head, as the model gave it, gets no check run either: the Markdown-only
        rule of R12 reads the changed paths itself and stops it. No check run with the conclusion success: after the
        person verdict, the post job records only the check run with the conclusion neutral that says that the head is
        not approved for the import, as no import check run of the head stands (OSSV-221's architect, 2026-11-24
        05:33Z). Waits-on-theorem with the steps of R12 for the variable's state: with no variable, each step that can
        follow; with the pair's import_paths, which take each of these paths, Sami's approval of the head for the
        import."""
        self.assertEqual(WF["env"]["SOUNDNESS_HOLD"], "true")
        for path, text, verdict, decision in (
                ("theories/Fd.v", "Lemma fd : True.\nProof. exact I. Qed.\n", "person", "person"),
                ("tools/gen_checker.py", "print('checker')\n", "person", "person"),
                ("dune", '(rule\n (alias runtest)\n (action (echo "checked\\n")))\n', "person", "person"),
                ("theories/Examples/rwx_flag_ns/SourceMemImage_seg_000.hex", "7f454c46\n", "person", "person"),
                ("tools/check_one.py", "print('one')\n", "person", "person"),
                ("tools/check_one.py", None, "pass", "markdown")):
            for value in (None, self.LPS):
                with self.subTest(path=path, verdict=verdict, variable=value is not None):
                    self.tearDown()
                    self.setUp()
                    if text is not None:
                        full = os.path.join(self.work, ".review", "head", path)
                        os.makedirs(os.path.dirname(full))
                        with open(full, "w") as f:
                            f.write(text)
                        with open(os.path.join(self.work, ".review", "pr.json"), "w") as f:
                            json.dump({"files": [{"path": path}]}, f)
                        with open(os.path.join(self.work, ".review", rules.SOUNDNESS_FILE), "w") as f:
                            json.dump(rules.proofs("HEAD", [{"filename": path, "previous_filename": None}], 1,
                                                   cwd=os.path.dirname(GITHUB_DIR)), f)
                        rc, out, reviewed = self.post("No blocking finding.", [], "No blocking finding.", "pass")
                        self.assertEqual((rc, reviewed["verdict"]), (0, verdict), out)
                    else:
                        reviewed = {"verdict": verdict}
                    got = self.judge([path], reviewed["verdict"], value)
                    if verdict == "person":
                        self.assertNotApproved(got, "person", decision)
                    else:
                        self.assertNotRecorded(got, decision)
                    step_line = self.PERSON if verdict == "person" else self.SOME if value is None else self.APPROVE
                    words = [self.MERGE] if value is None else [self.APPROVE]
                    body = self.assertWaits(got, step_line, *words, value=value)
                    # With no variable, no step of the live import; with it, no copy by hand.
                    self.assertNotIn("if the import copies each path" if value is None else self.COPY, body)

    def test_the_decide_step_logs_each_of_its_decisions_in_the_one_form(self):
        """OSSV-221's architect, 2026-11-24 14:36Z: the decide step of the post job logs its decision as "#<number> at
        <head>: decision <decision>, cause <cause>, read <time>", with a field where the decision needs one (rules.py
        log). The screened CI review of mallory's #7 at HEAD gives record for a pass and verdict for a blocking finding:
        the cause is the rule of R12, and the fields are the files that the step read and the files that #7 changes.
        When #7 is at OTHER_HEAD now, the decision is moved, with the cause head and the head that #7 has now. For an
        author with write access the decision is writer with the cause writer, and for an author whose access GitHub
        did not say it is writer with the cause access. The decisions that other tests of the post job pin are not
        pinned here."""
        read, files = self.REVIEWED["started"], "files 1, changed 1"
        for case, given, line in (
                ("a pass", {}, f"decision record, cause rule, read {read}, {files}"),
                ("a blocking finding", {"verdict": "blocking"}, f"decision verdict, cause rule, read {read}, {files}"),
                ("a head that moved", {"now": OTHER_HEAD},
                 f"decision moved, cause head, read {read}, now {OTHER_HEAD}"),
                ("an author with write access", {"trust": dict(self.REVIEWED, outside="false", kind="writer")},
                 f"decision writer, cause writer, read {read}"),
                ("an author whose access GitHub did not say",
                 {"trust": dict(self.REVIEWED, outside="false", kind="unknown")},
                 f"decision writer, cause access, read {read}")):
            with self.subTest(case=case):
                start = len(self.logs)
                self.judge(["README.md"], value=self.LPS, **given)
                self.assertIn(f"#7 at {HEAD}: {line}\n", "\n".join(self.logs[start:]))

    def test_a_new_head_after_an_approved_one_gets_no_check_run_until_it_passes(self):
        """HEAD got the check run. The author pushed OTHER_HEAD: the post job of HEAD's review that runs after the push
        records nothing on either head, and the labels stay; a relabel of OTHER_HEAD, whose only review comment names
        HEAD, records nothing; a blocking finding at OTHER_HEAD records only the check run with the conclusion neutral
        that says that OTHER_HEAD is not approved for the import, as no import check run of OTHER_HEAD stands
        (OSSV-221's architect, 2026-11-24 05:33Z). Once the review passes OTHER_HEAD, the check run is on OTHER_HEAD."""
        self.assertRecorded(self.judge(["README.md"], value=self.LPS), self.LPS)
        got = self.judge(["README.md"], value=self.LPS, now=OTHER_HEAD)
        self.assertNotRecorded(got, "moved")
        self.assertEqual((got["labels"], got["comments"]), ([], []))
        self.assertIn(f"#7 moved from {HEAD} to {OTHER_HEAD}, so the workflow changes neither its labels nor its label "
                      "comment.", got["log"])
        got = self.judge(["README.md"], value=self.LPS, then=OTHER_HEAD)
        self.assertNotRecorded(got, "moved")
        relabel = dict(self.RELABEL, head=OTHER_HEAD)
        got = self.judge(["README.md"], value=self.LPS, trust=relabel, event="workflow_dispatch", now=OTHER_HEAD,
                         comments=[review_of(HEAD)])
        self.assertNotRecorded(got, "screen")
        self.assertEqual((got["labels"], got["comments"]), ([], []))
        pushed = dict(self.REVIEWED, head=OTHER_HEAD)
        self.assertNotApproved(self.judge(["README.md"], "blocking", self.LPS, trust=pushed, now=OTHER_HEAD),
                               "blocking", "verdict", OTHER_HEAD)
        self.assertRecorded(self.judge(["README.md"], value=self.LPS, trust=pushed, now=OTHER_HEAD), self.LPS,
                            OTHER_HEAD)

