    def test_a_relabel_applies_the_decision_again_to_its_head_with_no_model(self):
        """A relabel by hand of mallory's pull request: the trust job gives the outsider, no job runs a model, and the
        post job takes the verdict from the marker of the review comment that names the head. A pass records the check
        run, and a person verdict gives the person's step and the approval for the import, with review-held left on.
        A head that no review names and a review comment that is not the workflow's record nothing, and their labels
        stay. A writer's pull request records nothing either (its decision is writer), and loses waits-on-theorem: a
        writer's item has no state label."""
        self.permissions(alice="write", mallory="read")
        self.serve_item(7, "mallory", kind="pr", head=HEAD)
        rc, out, trust = self.run_trust("workflow_dispatch", actor="alice", task="relabel", head=HEAD)
        self.assertEqual((rc, trust.get("task"), trust.get("route"), trust.get("outsider")),
                         (0, "relabel", "review", "mallory"), out)
        self.serve_item(7, "alice", kind="pr", head=HEAD)
        rc, out, writer = self.run_trust("workflow_dispatch", actor="alice", task="relabel", head=HEAD)
        self.assertEqual((rc, writer.get("task"), writer.get("outsider")), (0, "relabel", ""), out)
        self.assertEqual(ran_jobs(run_graph(trust, github={"github.event_name": "workflow_dispatch"})),
                         {"trust", "post", "comment"})
        relabel = {k: trust[k] for k in ("task", "route", "outsider", "outside", "number", "head", "started")}
        got = self.judge(["README.md"], value=self.LPS, trust=relabel, event="workflow_dispatch",
                         comments=[review_of(HEAD)])
        self.assertRecorded(got, self.LPS)
        self.assertEqual((got["labels"], got["comments"]), ([], []))
        got = self.judge(["README.md"], value=self.LPS, trust=relabel, event="workflow_dispatch",
                         comments=[review_of(HEAD, "person")])
        self.assertNotRecorded(got, "person")
        self.assertWaits(got, self.PERSON, f"{self.ANSWERED} {self.APPROVE}", value=self.LPS)
        self.assertNotIn(["--method", "DELETE", f"repos/{REPO}/issues/7/labels/review-held"], gh_calls(self.api))
        for case, trusted, comments in (
                ("no review", relabel, []),
                ("another account's markers", relabel, [review_of(HEAD, login="mallory")]),
                ("a writer's pull request", dict(relabel, outsider=writer["outsider"], outside=writer["outside"]),
                 [review_of(HEAD)])):
            with self.subTest(case=case):
                got = self.judge(["README.md"], value=self.LPS, trust=trusted, event="workflow_dispatch",
                                 comments=comments, labels=("review-held", THEOREM_LABEL))
                self.assertNotRecorded(got, "writer" if case == "a writer's pull request" else "screen")
                want = [("-", THEOREM_LABEL)] if case == "a writer's pull request" else []
                self.assertEqual((got["labels"], got["comments"]), (want, []))

    def test_a_relabel_records_the_check_run_only_for_a_head_that_a_screen_passed(self):
        """R12 (review round 1): alice, a writer, runs the review of mallory's pull request by hand with no
        -f screen=true. The trust job gives the route review and no outsider, so no screen runs, and the review comment
        of that run holds no marker <!-- review-screened <head> -->. The review passes a change of Markdown files
        alone. A relabel of the head then records no import check run: its decision is screen, and the label comment
        says that no screen passed the head. The same path after a run whose route was screen and whose screen passed
        records the check run: the review comment of that run holds the marker."""
        self.permissions(alice="write", mallory="read")
        self.serve_item(7, "mallory", kind="pr", head=HEAD)
        self.serve(f"repos/{REPO}/actions/runs", {"workflow_runs": []})
        rc, out, by_hand = self.run_trust("workflow_dispatch", actor="alice")
        self.assertEqual((rc, by_hand.get("task"), by_hand.get("route"), by_hand.get("outsider")),
                         (0, "review", "review", ""), out)
        rc, out, trust = self.run_trust("workflow_dispatch", actor="alice", task="relabel", head=HEAD)
        self.assertEqual((rc, trust.get("task"), trust.get("outsider")), (0, "relabel", "mallory"), out)
        relabel = {k: trust[k] for k in ("task", "route", "outsider", "outside", "number", "head", "started")}
        for route, screen, screened in ((by_hand["route"], "", False), ("screen", "clean", True)):
            with self.subTest(route=route):
                rc, out, made = self.post("No blocking finding.", [], "No blocking finding.", "pass", route=route,
                                          screen=screen)
                self.assertEqual(rc, 0, out)
                self.assertEqual(f"\n<!-- review-verdict {HEAD} pass -->\n<!-- review-screened {HEAD} -->\n"
                                 in made["body"], screened, made["body"])
                self.assertEqual(f"<!-- review-screened {HEAD} -->" in made["body"], screened, made["body"])
                review = {"id": 30, "user": {"login": BOT}, "created_at": OLD, "updated_at": OLD, "body": made["body"]}
                got = self.judge(["README.md"], value=self.LPS, trust=relabel, event="workflow_dispatch",
                                 comments=[review])
                if screened:
                    self.assertRecorded(got, self.LPS)
                else:
                    self.assertNotRecorded(got, "screen")
                    self.assertWaits(got, self.SOME, rules.UNSCREENED, value=self.LPS)

    # The trust job's outputs of alice's review by hand of mallory's pull request #7 at its head, with no screen.
    BY_HAND = {"task": "review", "route": "review", "outsider": "", "outside": "true", "number": "7", "head": HEAD,
               "started": PostLabelTest.STARTED}

    def recorded(self):
        """The check run that the review of #7 at HEAD recorded, as GitHub lists it (id 901, of the OSS Verify App),
        and three that a withdrawal leaves: one of #8 at the same commit, one of another App, and one that is neutral
        already."""
        got = self.judge(["README.md"], value=self.LPS)
        self.assertRecorded(got, self.LPS)
        (_token, body), = got["checks"]
        listed = dict(body, id=901, app={"id": VERIFY_APP_ID})
        return listed, [dict(listed, id=902, external_id=f"8:{HEAD}"), dict(listed, id=903, app={"id": 1}),
                        dict(listed, id=904, conclusion="neutral")]

    @staticmethod
    def withdrawn(check, why, run, at, id_=None):
        """check as GitHub lists it once run withdrew it at the time at for its own verdict or screen why: the request
        of rules.withdrawal for its own reason, whose summary names run and at (OSSV-221's architect, 2026-11-23
        03:06Z). With id_, as the check run of that id."""
        return {**check, **rules.withdrawal("7", HEAD, why, check["output"]["text"], run, "own", "", at),
                "completed_at": at, **({} if id_ is None else {"id": id_})}

    @staticmethod
    def applied(check, got):
        """check as GitHub lists it once the post job that judge ran (got) withdrew it: the conclusion, completed_at and
        output of its request."""
        (request,) = [b for _t, e, b in got["withdrawn"] if e == f"repos/{REPO}/check-runs/{check['id']}"]
        return {**check, **request}

    def test_a_later_review_or_screen_of_a_head_that_does_not_meet_r12_withdraws_its_check_run(self):
        """R12 (spec v71): the review of HEAD recorded the check run with conclusion success. A later review of the same
        head that gives the verdict person (alice's review by hand, which runs no screen), or a blocking finding (a
        review whose screen passed), or a later screen that holds the head, and the relabel of a head whose review
        comment gives the verdict person (the App's retry of a post job that failed): the post job of that run reads
        the check runs of HEAD with its own token, and then updates the check run of #7, with token A, to the
        conclusion neutral. The request's output title names #7 and says why, and its output text is the check run's
        own, the marker line of the value that it recorded. Its summary also names the run that withdraws it (run 100),
        HEAD, the reason and the time from which the withdrawal counts, and its completed_at is the time of the
        withdrawal: a withdrawal is itself the record of its reason (OSSV-221's architect, 2026-11-23 01:47Z and
        03:06Z). For its own verdict or screen, that time is when run 100 read the item, its trust job's started, never
        the time of the withdrawal (2026-11-24 05:23Z); the record of 901 names a read at that same time, so the tie
        withdraws it. At that tie run 100 is not a later run, so its title and summary name run 100, and the log names
        this run (the tester's fresh reader of round 22, row 4; rules.py TIE_WITHDRAWN). For the relabel, whose review
        comment names no run, the workflow knows no time of that earlier run, so the time is that of the withdrawal
        (the fresh reader of round 19, F1 and S1). The relabel's texts do not say later, as the review that it reads can
        be older than the check run, and they give a past verdict (b7). The request names no name and no external_id,
        so both stay. The other check runs of the commit stay as they are. The logs of both steps name the import check
        run, and the first gives the decision withdraw, the cause, the read of this run and the time from which the
        withdrawal counts, in the form of rules.py log."""
        listed, others = self.recorded()
        person = ("because the review of run 100 has questions for Sami",
                  "The automated review in run 100 has questions for Sami.", "person")
        for case, verdict, trust, screen, comments, (why, said, reason) in (
                ("a review by hand with the verdict person", "person", self.BY_HAND, "", (), person),
                ("a screened review with a blocking finding", "blocking", None, "clean", (),
                 ("because the review of run 100 asks for a change",
                  "The automated review in run 100 asks for a change.", "blocking")),
                ("a screen that held the head", "pass", None, "held", (),
                 ("because the screen of run 100 held it", "The automated screen in run 100 held this head commit.",
                  "screen")),
                ("a relabel of a review with the verdict person", "", self.RELABEL, "", (review_of(HEAD, "person"),),
                 ("because an automated review of this head commit had questions for Sami",
                  "An automated review of this head commit had questions for Sami.", "person"))):
            with self.subTest(case=case):
                start = len(self.logs)
                got = self.judge(["README.md"], verdict, self.LPS, trust=trust, screen=screen, comments=comments,
                                 event="workflow_run" if trust is None else "workflow_dispatch",
                                 listed=[listed, *others])
                self.assertEqual((got["result"], got["checks"]), ("success", []), self.logs)
                self.assertEqual(got["steps"][MINT_A], "success")
                (token, endpoint, body), = got["withdrawn"]
                self.assertEqual((token, endpoint), ("token-A", f"repos/{REPO}/check-runs/901"))
                # The time of the withdrawal, in the form in which GitHub gives a time. For own, the withdrawal counts
                # from the time when run 100 read the item (OSSV-221's architect, 2026-11-24 05:23Z); for the relabel,
                # from the time of the withdrawal (2026-11-23 01:47Z and 03:06Z).
                at = body.pop("completed_at", "")
                self.assertTrue(rules.TIME.fullmatch(at), at)
                started = (trust or self.REVIEWED)["started"]
                ended = (f", for the reason `{reason}` of run 100 itself. The withdrawal counts from {started}, the "
                         "time when run 100 read the pull request." if trust is not self.RELABEL else
                         f" at {at}, for the reason `{reason}` of an earlier run. The workflow knows no time of that "
                         "run, so the withdrawal counts from this time.")
                self.assertEqual(body, {"status": "completed", "conclusion": "neutral", "output": {
                    "title": f"Not approved for the import: pull request #7 at {HEAD[:12]}, {why}",
                    "summary": f"{said} So this check is no longer an approval for the import. Run 100 of the review "
                               f"workflow withdrew it from head commit {HEAD}{ended}",
                    "text": listed["output"]["text"]}})
                self.assertEqual(rules.withdrawn_by(dict(body, conclusion="neutral"), HEAD),
                                 (reason, "100", at if trust is self.RELABEL else started))
                self.assertMarker(body["output"]["text"], self.LPS)
                self.assertEqual(got["writes"], [["--method", "PATCH", f"repos/{REPO}/check-runs/901", "--input",
                                                  os.path.join(self.temp, "withdraw-901.json"), "--jq",
                                                  ".conclusion"]])
                self.assertEqual(got["read with"], {self.RUN_TOKEN})
                logs = "\n".join(self.logs[start:])
                counts = "none" if trust is self.RELABEL else started
                self.assertIn(f"#7 at {HEAD}: decision withdraw, cause {reason}, read {started}, check 901, from "
                              f"{counts}\n", logs)
                self.assertIn(f"Withdrew the import check run 901 of {HEAD}: its conclusion is now neutral.", logs)

    def test_a_relabel_that_withdraws_for_a_review_older_than_the_check_run_does_not_call_that_review_later(self):
        """b7 (the tester's fresh reader of round 19, F1): run 80's screened review of HEAD of mallory's #7 gave a
        blocking finding or the verdict person 60 minutes ago. Run 90 then rescreened HEAD, its screen and review
        passed, and its post job recorded check run 901 just now; its comment job has not posted its review yet (post
        jobs share post-7, comment jobs label-7, so a relabel queued behind run 90's post job reads the comments first).
        The relabel reads run 80's review as the newest and withdraws 901 for it. That review is older than 901, so the
        check run's title and summary, and the step's log, must not say that a later review asks for a change or has
        questions: the withdrawal's own summary names run 80 or an earlier run as the source, which came before 901.
        At 8407477d the title says 'because a later review asks for a change' and the summary starts 'A later
        automated review of this head commit asks for a change.' (rules.py withdrawal uses WITHDRAWN for every kind but
        owed; review.yml's withdraw step keeps who='a later review' for a relabel)."""
        listed, _others = self.recorded()
        listed = dict(listed, completed_at=ago(1))
        old = {"id": 40, "user": {"login": BOT}, "created_at": ago(120), "updated_at": ago(120),
               "body": rules.label_comment("import", "", [rules.import_marker(HEAD, self.LPS)])}
        for verdict in ("blocking", "person"):
            with self.subTest(verdict=verdict):
                earlier = review_of(HEAD, verdict, at=ago(60), run=80)
                start = len(self.logs)
                got = self.judge(["README.md"], value=self.LPS, trust=dict(self.RELABEL, started=ago(-1)),
                                 event="workflow_dispatch", comments=[earlier, old], listed=[listed])
                self.assertEqual((got["result"], got["post"]["withdrawn"]), ("success", HEAD), self.logs)
                (_token, endpoint, body), = got["withdrawn"]
                self.assertEqual(endpoint, f"repos/{REPO}/check-runs/901")
                self.assertGreater(listed["completed_at"], earlier["updated_at"])
                self.assertNotIn("later", body["output"]["title"])
                self.assertNotIn("A later", body["output"]["summary"])
                self.assertNotIn("because a later review", "\n".join(self.logs[start:]))

    def test_a_held_screen_of_a_review_a_rescreen_or_an_approval_withdraws_the_check_run_of_its_head(self):
        """R12 (review round 1, part I): the review of HEAD recorded the check run with conclusion success. A later
        screen of HEAD that holds it, in the run of each task that screens a pull request: a review (of a CI run, or by
        hand), a rescreen and an approval (workflow_dispatch). The post job runs with no review job, while the
        environment post holds the App's key. Its decision does not run, as no screen passed, and its step "Find the
        import check runs that a later review or screen withdraws" finds the check run of #7. The next steps mint
        token A and withdraw it, and no other step of the job stops them. The record of 901 names a read at the time
        when this run read the item: at that tie, the title names run 100, not a later screen (rules.py
        TIE_WITHDRAWN)."""
        listed, others = self.recorded()
        find = "Find the import check runs that a later review or screen withdraws"
        for task, event in (("review", "workflow_run"), ("review", "workflow_dispatch"),
                            ("rescreen", "workflow_dispatch"), ("approve", "workflow_dispatch")):
            with self.subTest(task=task, event=event):
                got = self.judge(["README.md"], value=self.LPS, trust=dict(self.REVIEWED, task=task), screen="held",
                                 event=event, listed=[listed, *others])
                self.assertEqual(got["result"], "success", self.logs[-3:])
                self.assertEqual((got["steps"][self.DECIDE], got["steps"][find], got["steps"][MINT_A]),
                                 ("skipped", "success", "success"))
                (token, endpoint, body), = got["withdrawn"]
                self.assertEqual((token, endpoint, body["conclusion"], body["output"]["title"]),
                                 ("token-A", f"repos/{REPO}/check-runs/901", "neutral",
                                  f"Not approved for the import: pull request #7 at {HEAD[:12]}, because the screen "
                                  "of run 100 held it"))

    def test_a_later_screen_or_review_of_an_outside_pull_request_whose_authors_access_github_cannot_say_withdraws(self):
        """Ruling (1) of OSSV-221's architect (2026-11-20 13:26Z) and R12: an item whose author's write access GitHub
        cannot say gets no outside label, but stays an outsider's for the import check run. The review of mallory's #7
        at HEAD recorded the check run with conclusion success. Then alice reviews #7 by hand with the screen first,
        while GitHub's permission API does not answer for mallory: the trust job gives the route screen with no
        outsider, and its outside is false. The screen holds HEAD, or it passes and the review gives a blocking finding:
        as when GitHub says that mallory has no write access (outside true), the post job reads the check runs of HEAD
        and withdraws the check run of #7, with token A, to the conclusion neutral."""
        listed, others = self.recorded()
        find = "Find the import check runs that a later review or screen withdraws"
        self.serve(f"repos/{REPO}/actions/runs", {"workflow_runs": []})
        for case, permission, outside in (("GitHub does not say", None, "false"), ("no write access", "read", "true")):
            if permission:
                self.permissions(mallory=permission)
            self.serve_item(7, "mallory", kind="pr", head=HEAD)
            rc, out, trust = self.run_trust("workflow_dispatch", actor="alice", screen="true")
            self.assertEqual((rc, trust.get("task"), trust.get("route"), trust.get("outsider"), trust.get("outside")),
                             (0, "review", "screen", "", outside), out)
            trust = {k: trust[k] for k in ("task", "route", "outsider", "outside", "number", "head", "started")}
            for screen, verdict, why in (("held", "pass", "because a later screen held it"),
                                         ("clean", "blocking", "because a later review asks for a change")):
                with self.subTest(case=case, screen=screen, verdict=verdict):
                    got = self.judge(["README.md"], verdict, self.LPS, trust=trust, screen=screen,
                                     event="workflow_dispatch", listed=[listed, *others])
                    self.assertEqual((got["result"], got["steps"].get(find, "skipped")), ("success", "success"),
                                     self.logs[-3:])
                    (token, endpoint, body), = got["withdrawn"]
                    self.assertEqual((token, endpoint, body["conclusion"], body["output"]["title"]),
                                     ("token-A", f"repos/{REPO}/check-runs/901", "neutral",
                                      f"Not approved for the import: pull request #7 at {HEAD[:12]}, {why}"))

    def test_no_check_run_on_the_head_or_a_later_review_that_meets_r12_withdraws_nothing(self):
        """A later review with the verdict person of a head that has no check run of the App for #7 with the conclusion
        success (none, or only the others of the commit): the post job reads the check runs of the head and sends no
        PATCH. For mallory, an outside author, it records with token A only the check run with the conclusion neutral
        that says that the head is not approved for the import, and its log says so (OSSV-221's architect, 2026-11-24
        05:33Z). For a writer, whose runs record no check run, it mints no token A, and its log gives the decision
        clear: the head has no import check run to withdraw. A later review of the head that meets the rule leaves the
        check run with conclusion success: the post job records a new one, and withdraws none. The withdrawal of run
        90 on the head, 90 minutes ago, is older than the start of that review, 40 minutes ago, so it stands in the way
        of no record (OSSV-221's architect, 2026-11-23 18:38Z)."""
        listed, others = self.recorded()
        for case, checks in (("no check run", []), ("only the others", others)):
            for outside in ("true", "false"):
                with self.subTest(case=case, outside=outside):
                    start = len(self.logs)
                    got = self.judge(["README.md"], "person", self.LPS, trust=dict(self.BY_HAND, outside=outside),
                                     event="workflow_dispatch", listed=checks)
                    self.assertEqual((got["result"], got["withdrawn"]), ("success", []), self.logs)
                    self.assertIn(f"repos/{REPO}/commits/{HEAD}/check-runs", self.calls())
                    log = "\n".join(self.logs[start:])
                    if outside == "true":
                        self.assertNotApproved(got, "person")
                        self.assertIn(f"#7 at {HEAD}: decision not-approved, cause person, read "
                                      f"{self.BY_HAND['started']}\n", log)
                    else:
                        self.assertEqual((got["writes"], got["steps"][MINT_A]), ([], "skipped"), log)
                        self.assertIn(f"#7 at {HEAD}: decision clear, cause person, read {self.BY_HAND['started']}\n",
                                      log)
        aged = self.withdrawn(dict(listed, id=904), "blocking", "90", ago(90))
        got = self.judge(["README.md"], value=self.LPS, trust=dict(self.REVIEWED, started=ago(40)),
                         listed=[listed, *others[:2], aged])
        self.assertRecorded(got, self.LPS)
        self.assertEqual(got["withdrawn"], [])

    def test_a_writers_pull_request_whose_head_an_outsider_pushed_gets_no_check_run(self):
        """R12 (spec, Terms): the import check run is for an outside pull request alone, whose author has no write
        access. eve, with read access, pushes to the branch of alice's #7. The trust job of that CI run screens it on
        eve: its outsider is eve, and its outside is false. The screen passes, and the review passes a change of
        Markdown files alone: no check run, and the decision is writer. R5 (ruling 1 of OSSV-221's architect): the pull
        request is no outside item, so the comment job sets no state label and posts no label comment. The same push
        to mallory's #7 records it."""
